   299	    for (const zone of this.sceneTriggerZones) {
   300	      if (zone.sceneId !== DEFAULT_SCENE_ID) continue;
   301	      if (zone.allowedSpawnKeys && !zone.allowedSpawnKeys.includes(player.spawnKey || "sp_player_default")) {
   302	        continue;
   303	      }
   304	
   305	      const dx = player.position.x - zone.x;
   306	      const dy = player.position.y - zone.y;
   307	      const distSq = dx * dx + dy * dy;
   308	
   309	      if (distSq <= zone.radius * zone.radius) {
   310	        this.playerSceneTriggerCooldowns.set(player.id, now + SCENE_TRIGGER_COOLDOWN_MS);
   311	        this.teleportPlayer(player, zone.targetSpawnKey);
   312	        break;
   313	      }
